/* Types */
export type Account = {
	id: string,
	email: string | null,
	plan: string | null,
};

/**
 *  条漫首尾的广告带高度，单位为原始源图像素。
 * 
 *  两条高度各自锚定在源图的一端，**不锚定在顶端**。每章的总高不同，从顶端起算的位置会随
 *  章节长度漂移；锚定底端才能让同一个数值在整部作品里通用。
 */
export type AdBands = {
	/**  自源图顶端起算的首条高度。0 表示这一端没有广告。 */
	head: number,
	/**  自源图底端起算的尾条高度。0 表示这一端没有广告。 */
	tail: number,
};

export type AgentStatus = {
	account: Account | null,
	models: CodexModel[],
	config: Config,
	running: RunId | null,
};

export type AnalysisRegion = {
	id: EntityId,
	parent: EntityId | null,
	geometry: Geometry,
	kind: string,
	label: string | null,
};

export type Bounds = {
	x: number,
	y: number,
	width: number,
	height: number,
};

export type CaiyunConfig = Record<string, never>;

export type CanvasBytes = number[];

export type CanvasGeneration = number;

export type CanvasPagePreparation = {
	revision: Revision,
	page: Page,
};

export type CanvasState = {
	page: EntityId | null,
	revision: Revision | null,
	generation: number,
	size: [number, number],
	element_frames: TransformFrame[],
};

/**
 *  一章的源形态。导入时由用户选定，不靠自动判定：页漫里存在高幅面单页，条漫的形态也可能
 *  与之接近，判错就是整章被切碎或完全没切。
 */
export type ChapterKind = 
/**  页漫：多张普通页，每张一页，不切。 */
"manga" | 
/**  条漫：一张纵向长图，按可读高度切页。 */
"webtoon";

/**
 *  一章的身份：漫画目录名 + 章目录名。
 * 
 *  内核认不出这两个名字——它只收一个路径，项目身份是 `create` 时生成的 `DocumentId`，与路径和
 *  名字都无关。所以路径推导是这一层的事，而推导所需的全部信息就是这两段目录名。合成一个结构，
 *  章项目路径便只有一个出处。
 */
export type ChapterRef = {
	/**  漫画目录名，库根目录的直接子目录。 */
	series: string,
	/**  章目录名，漫画目录下的直接子目录。 */
	chapter: string,
};

/**  一章的编排状态。 */
export type ChapterStatus = 
/**  已在索引中登记，章项目尚未建立。 */
"pending" | 
/**  章项目已建立，可以进入处理流程。 */
"ready" | "done";

