export type ProviderConfig = { provider: "local"; settings: LocalConfig } | { provider: "openai"; settings: OpenAiConfig } | { provider: "gemini"; settings: GeminiConfig } | { provider: "claude"; settings: ClaudeConfig } | { provider: "grok"; settings: GrokConfig } | { provider: "minimax"; settings: MiniMaxConfig } | { provider: "deepseek"; settings: DeepSeekConfig } | { provider: "mimo"; settings: MiMoConfig } | { provider: "openai-compatible"; settings: OpenAiCompatibleConfig } | { provider: "openrouter"; settings: OpenRouterConfig } | { provider: "lm-studio"; settings: LmStudioConfig } | { provider: "deepl"; settings: DeepLConfig } | { provider: "google-cloud-translation"; settings: GoogleCloudConfig } | { provider: "caiyun"; settings: CaiyunConfig };

export type ProviderPreference = {
	name: string,
	config: ProviderConfig,
	credential: CredentialInput | null,
};

export type ProviderPreferences = {
	entries: ProviderPreference[],
};

export type Quantization = {
	id: string,
	name: string,
	downloaded: boolean,
};

export type RasterLayerKind = "cleanup" | "paint";

export type Reasoning = "low" | "medium" | "high" | "xhigh" | "max" | "ultra";

export type Revision = number;

export type RoremMixedConfig = {
	prompt?: string,
	negative_prompt?: string,
};

export type RunId = string;

export type Scope = { scope: "project" } | { scope: "pages"; value: EntityId[] } | { scope: "region"; value: {
	page: EntityId,
	bounds: Bounds,
} } | { scope: "entities"; value: EntityId[] };

/**  一部漫画。 */
export type Series = {
	/**
	 *  目录名，同时是这部漫画的标识。
	 * 
	 *  它由所在位置决定，所以读取时以目录名为准覆盖文件里的值；写进文件只是为了在目录被
	 *  改名之后还能看出原委。
	 */
	id: string,
	title: string,
	/**  连载为 `true`，单行为 `false`。只影响界面呈现，不改变任何处理逻辑。 */
	serial: boolean,
	/**  封面文件名。`None` 表示用户没有指定，界面渲染占位图。 */
	cover: string | null,
	chapters: SeriesChapter[],
	settings: SeriesSettings,
	/**
	 *  生肉来源。未绑定时自动更新不可用——这是「用户还没指定站点」，不是配置坏了。
	 * 
	 *  缺键即未绑定，所以老索引读得出来，不需要迁移。
	 */
	source?: SeriesSource | null,
};

/**  漫画里的一章。 */
export type SeriesChapter = {
	seq: number,
	title: string,
	/**  章目录名，父目录由这部漫画的位置决定，两段合起来才是章的引用。 */
	chapter: string,
	/**  这一章的源形态，决定导入时是否切页。 */
	kind: ChapterKind,
	/**  编排状态，与章项目内部的处理状态分开。 */
	status: ChapterStatus,
};

/**
 *  一次批量实际注入进去的东西。
 * 
 *  只需要报命中数：上文不再走注入通道，它的总量由用户自己设的 `context_pages` 页数上限约束，不存在
 *  静默截断，因此没有「被丢掉多少」需要解释。
 */
export type SeriesRun = {
	/**  跑完的章数。 */
	chapters: number,
	/**  术语表里出现在原文中的条数。整批共用同一份原文，所以这个值在批内不变。 */
	matched: number,
	/**  当前服务商不接受提示词，这一批的注入内容全部无效。 */
	unsupported: boolean,
};

/**
 *  漫画级的翻译资料与配置。
 * 
 *  归属漫画而不是章：资料的生命周期跟着整部作品走，而章项目会被删除重建。
 */
export type SeriesSettings = {
	/**  条漫首尾的站点广告高度，导入时从源图裁掉。 */
	ad: AdBands,
	/**
	 *  本作特有的翻译风格约定，手写散文。
	 * 
	 *  空串表示没有。全局指导仍然保留，排在它之后作为跨作品的个人口味兜底。
	 */
	guidance: string,
	/**
	 *  术语表文件名，与索引同目录。`None` 表示还没有术语表。
	 * 
	 *  存文件名而不是内容：术语表条目多且每条都可能被编辑，放进索引会让改一个词条就要重写
	 *  整个编排文件。`Some` 但文件不存在是合法状态，读取时当作空表。
	 */
	glossary: string | null,
	/**
	 *  章内上文回溯的页数：翻译第 N 页时带上第 N−1 到第 N−N 页的成对双语对照。0 表示不注入。
	 * 
	 *  这不是章的资料而是**运行参数**——它决定翻译阶段每次请求带多少先例，所以归到批量执行时
	 *  写进管线配置，而不像指导与术语表那样渲染进附加说明。上文窗口跨章连续，所以这一个值同时是
	 *  章内与章外的回溯距离：翻到本章第 1 页时窗口整段来自上一章末尾，翻到第 2 页时让出一页换成本章
	 *  第 1 页，以此类推。合适的距离取决于模型与作品，只能实测确定，所以它是用户可调的；硬上限由
	 *  `koharu_pipeline::MAX_CONTEXT_PAGES` 兜住。
	 */
	context_pages?: number,
};

/**
 *  生肉来源站点。
 * 
 *  枚举而不是自由字符串：每种站点的地址模板与页面形状都由 `koharu-source` 里对应的模块拥有，
 *  站点名只是派发的依据。枚举让「不支持的站点」在类型上不可表达，也免掉了一份中央白名单。
 */
export type SeriesSite = 
/**  OmegaScans（`omegascans.org`）。 */
"omega_scans";

/**
 *  这部漫画的生肉来自哪里。
 * 
 *  只有 slug 是身份。站点给的其余信息（作品号、章节地址、更新时间）都是随时能重查的派生值，
 *  落进索引就等于把自己绑死在站点的当前格式上。
 */
export type SeriesSource = {
	site: SeriesSite,
	/**  作品在站点地址里的那一段，例如 `love-quest`。 */
	slug: string,
};

/**  首页漫画柜需要的一条漫画。 */
export type SeriesSummary = {
	id: string,
	title: string,
	serial: boolean,
	/**  封面文件名，`None` 表示用占位图。 */
	cover: string | null,
	chapters: number,
	done: number,
};

/**
 *  站点上一篇作品的一章。
 * 
 *  同时是「检查更新」的返回项与「开始下载」的入参：前端原样回传后端刚给的东西，后端因此
 *  不必为了拿 slug 再把整个章节列表拉一遍。
 */
export type SourceChapter = {
	/**  归一化后的章名，也就是本地将用的 `SeriesChapter.title`。 */
	name: string,
	/**  阅读页地址的最后一段。 */
	slug: string,
};

/**  检查更新的结果。 */
export type SourceCheck = {
	/**  站点上的作品名，用来核对绑对了没有。 */
	title: string,
	/**  下载时会用的源形态。界面照它显示，用户才知道条漫漫画不会被当成页漫。 */
	kind: ChapterKind,
	/**  本地还没有的章节，按章号升序。 */
	missing: SourceChapter[],
};

/**  一次下载任务的进度。 */
export type SourceFetch = {
	id: number,
	series: string,
	chapter: string,
	/**  从 1 起算，让界面不必自己加。 */
	chapter_index: number,
	chapter_total: number,
	page_index: number,
	page_total: number,
	state: SourceFetchState,
	error: string | null,
};

export type SourceFetchState = "running" | 
/**  全部选中章节都已进库。 */
"finished" | 
/**  中途失败。已经进库的章节仍然留在库里。 */
"failed" | 
/**  用户叫停。 */
"stopped";

export type SourceText = {
	text: string,
	language: string | null,
};

export type Stage = "detection" | "ocr" | "translation" | "inpainting";

export type StartupState = {
	preferences: Preferences,
	jobs: Job[],
	canvas: CanvasState,
};

export type TextAlignment = "Start" | "Center" | "End" | "Justify";

export type TextContent = {
	id: EntityId,
	source: SourceText | null,
	translation: Translation | null,
	role: string | null,
	source_region: EntityId | null,
};

export type TextLayoutKind = "point" | "paragraph";

export type ThumbnailBytes = number[];

export type TransformFrame = {
	element: EntityId,
	frame: Frame,
};

export type Translation = {
	text: string,
	language: string | null,
};

export type TranslationConfig = {
	model: ModelSelection,
	generation: GenerationConfig,
	target_language: string,
	instructions: string | null,
	/**
	 *  上文窗口的页数：翻译一页时带上它之前最近的若干页成对双语对照。0 表示不注入。
	 * 
	 *  窗口跨章边界连续，所以这一个值同时是章内与跨章的回溯距离，用户只调一个旋钮。走的是语境条目
	 *  通道而不是附加说明，因为附加说明是整批共用的一段散文，而上文的全部意义在于逐页不同
	 *  （见 `context` 模块）。值由漫画级设置给出，上限是 [`crate::MAX_CONTEXT_PAGES`]。
	 */
	context_pages?: number,
	/**
	 *  窗口里属于上一章的那几页：外层是页，内层是该页已成对的原文与译文，按阅读顺序。
	 * 
	 *  由漫画层在每章开始前写一次，跑批时翻完一章再用刚跑出来的译文覆盖给下一章，所以同一批里排在
	 *  后面的章吃到的是鲜的。单章运行没有「下一章」可覆盖，它读到的是漫画目录里已有的基线，也就是
	 *  上一章磁盘上已有的译文；那章还没翻过时是空的，此时窗口只有章内部分。
	 */
	prior_chapter_context?: TranslationContext[][],
};

export type TranslationContext = {
	source: string,
	translation: string,
};

export type TypesettingConfig = {
	font_families?: string[],
};

export type Typography = {
	preferred_font: string | null,
	font_weight: number | null,
	font_style: FontStyle | null,
	size: number | null,
	auto_fit: boolean,
	color: [number, number, number, number] | null,
	stroke_color: [number, number, number, number] | null,
	stroke_width: number | null,
	alignment: TextAlignment | null,
	writing_mode: WritingMode | null,
};

export type TypographyUpdate = {
	layer: EntityId,
	typography: Typography,
};

export type WritingMode = "Horizontal" | "Vertical";

/* Tauri Specta runtime */
function mapChannel<T>(channel: Channel<T>, deserialize: (payload: any) => T): Channel<T> {
    return new Channel((payload) => channel.onmessage(deserialize(payload)));
}

